mapper.sql:
WHERE rc.camp_id = #{campId}
  AND rc.status = 1
  AND rc.is_deleted = 0

    AND rc.poi_id = #{poiId}


    AND rc.group_id = #{roomCategoryGroupId}


    AND rc.name LIKE CONCAT('%', #{roomCategoryName}, '%')


    AND (
        rc.name LIKE CONCAT('%', #{keyword}, '%')
        OR rc.display_name LIKE CONCAT('%', #{keyword}, '%')
    )


    AND EXISTS (
        SELECT 1
        FROM channel_room_category_rel rel
        JOIN channel_account ca ON ca.account_id = rel.account_id
            AND ca.camp_id = rel.camp_id
        WHERE rel.camp_id = rc.camp_id
          AND rel.room_category_id = rc.room_category_id
          AND ca.channel_id = #{channelId}
    )

mapper.select:
SELECT CAST(r.room_category_id AS CHAR) AS roomCategoryId, CAST(r.room_id AS CHAR) AS roomId, r.room_name AS roomName, NULL AS yuejumaAddress FROM room r WHERE r.status = 1 AND r.is_deleted = 0 AND r.room_category_id IN
#{roomCategoryId}
ORDER BY r.room_category_id ASC, r.sort_no ASC, r.room_id ASC
